const assignmentUI=createAssignmentUI({getState:()=>state,isAgent:()=>view==='agent',commit,rerender:render,showModal,closeModal,closeDrawer,toast,openCase,refreshCase:refreshOpenCase,record,fromParis,showOverview:()=>{teamMode='overview';setView('teams')}});
