let toastTimer;let pointerDrag=null,suppressClick=false;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',5500)}
function save(){try{ensureAssignmentData(state);localStorage.setItem(KEY,JSON.stringify(state));storageRevision++;storageError='';return true}catch{storageError='Stockage local indisponible ou saturé. Exportez vos données JSON avant de quitter cette page.';toast(storageError,true);return false}}
function commit(message){const ok=save();render();if(message)toast(ok?message:message+' · en mémoire uniquement',!ok)}
function badge(d){const p=priority(d,state.settings);return '<span class="priority-badge '+p.key+'" title="'+esc(p.reason)+'"><span class="dot '+p.key+'"></span>'+PRIORITIES[p.key].label+'</span>'}
function date(v,short=false){return v?new Intl.DateTimeFormat('fr-FR',{timeZone:'Europe/Paris',day:'2-digit',month:'short',...(short?{}:{hour:'2-digit',minute:'2-digit'})}).format(new Date(v)):'Non renseignée'}
function age(d){const h=Math.max(0,Math.floor((Date.now()-Date.parse(d.opened))/3600000));return h<24?h+' h':Math.floor(h/24)+' j '+h%24+' h'}
const agentName=id=>state.agents.find(a=>a.id===id)?.name||'Non affecté';
const assignedNames=d=>assigneeIds(d).map(agentName).join(', ')||'Non affecté';
const opt=(value,label,current)=>'<option value="'+esc(value)+'"'+(value===current?' selected':'')+'>'+esc(label)+'</option>';
const options=(list,current)=>list.map(v=>opt(v,v,current)).join('');
const countryOptions=(current,all=false)=>(all?opt('','Tous les pays',current):'')+COUNTRIES.map(c=>opt(c.code,c.flag+' '+c.name,current)).join('');
const agentOptions=(current,all=false)=>(all?opt('','Tous les chargés',current):opt('','Non affecté',current))+state.agents.map(a=>opt(a.id,a.name,current)).join('');
const field=(label,name,type,value,extra='')=>'<label class="field">'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>';
const select=(label,name,opts,extra='')=>'<label class="field">'+label+'<select name="'+name+'" '+extra+'>'+opts+'</select></label>';
function setView(v){assignmentUI.close();if(v==='tvh'){filters.region=null;if(!filters.country)filters.country='FR'}if(v==='map'&&!['map','tvh','flux'].includes(view)){mapFullscreen=true;document.body.classList.add('map-fullscreen')}if(v==='agent'){window.open('./?view=agent','manager-control-agent','width=420,height=810,resizable=yes,scrollbars=yes');return}if(!['map','tvh','flux'].includes(v)){mapFullscreen=false;document.body.classList.remove('map-fullscreen')}view=v;render();window.scrollTo({top:0,behavior:'instant'})}
function kpis(rows){
 const critical=rows.filter(d=>priority(d,state.settings).key==='critical').length,tvh=rows.filter(d=>d.tvh==='En cours').length,benef=rows.filter(waiting).reduce((n,d)=>n+d.groups.filter(g=>WAITING_BENEFITS.includes(g.status)).reduce((a,g)=>a+beneficiaryCount(g),0),0);
 const entries=[[view==='tvh'?'Dossiers TVH':'Dossiers actifs',rows.length,'files',COUNTRIES.filter(c=>rows.some(d=>d.country===c.code)).length+' pays représentés',''],['Dossiers non affectés',rows.filter(d=>!assigneeIds(d).length).length,'team','À répartir dans l’équipe',''],['Bénéficiaires en attente',benef,'team','Route ou villégiature',''],['TVH en cours',tvh,'truck','Véhicules en transit','green'],['Dossiers critiques',critical,'shield','Décision managériale','alert']];
 return '<div class="kpis">'+entries.map(([l,v,i,n,c])=>'<div class="kpi '+c+'"><div><span class="label">'+l+'</span><strong>'+v+'</strong><small>'+n+'</small></div><span class="kpi-icon">'+icon(i)+'</span></div>').join('')+'</div>';
}

function filterBar(){return '<div class="filters"><span class="filter-icon">'+icon('filter')+'</span><select aria-label="Filtrer par pays" data-filter="country" class="'+(filters.country?'filter-active':'')+'">'+countryOptions(filters.country,true)+'</select><select aria-label="Filtrer par chargé" data-filter="agent">'+agentOptions(filters.agent,true)+opt('none','Non affecté',filters.agent)+'</select><select aria-label="Filtrer par priorité" data-filter="priority">'+opt('','Toutes priorités',filters.priority)+Object.entries(PRIORITIES).map(([k,p])=>opt(k,p.label,filters.priority)).join('')+'</select><select aria-label="Filtrer par étape" data-filter="stage">'+opt('','Toutes les étapes',filters.stage)+options(STAGES,filters.stage)+'</select><select aria-label="Filtrer par assistance" data-filter="type">'+opt('','Toute assistance',filters.type)+options(['Panne','Accident'],filters.type)+'</select><input aria-label="Rechercher un dossier" placeholder="N° dossier, lieu, statut…" data-filter="q" value="'+esc(filters.q)+'">'+(filters.region?'<button class="small region-chip" data-action="clear-region">'+esc(filters.region.properties.name)+' ×</button>':'')+'<button class="small ghost" data-action="dates" title="Filtrer par dates">'+icon('clock')+'</button><button class="small ghost" data-action="reset-filters" aria-label="Réinitialiser les filtres">'+icon('close')+'</button></div>'}
function shell(){const nav=[['map','map','CARTE'],['tvh','truck','TVH'],['flux','flow','FLUX'],['cases','files','DOSSIERS'],['teams','team','ÉQUIPES & AFFECTATIONS'],['dashboard','chart','DASHBOARD'],['archives','archive','ARCHIVES']];
 return '<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-symbol">'+icon('chart')+'</div><div class="brand-name">Manager<br>Control<small>Supervision ETR</small></div></div><div class="nav-label">ESPACE OPÉRATIONS</div><nav class="nav" aria-label="Navigation principale">'+nav.map(([v,i,l])=>'<button data-view="'+v+'" class="'+(view===v?'active':'')+'" title="'+l+'" aria-label="'+l+'">'+icon(i)+'<span>'+l+'</span></button>').join('')+'</nav><div class="side-bottom"><a class="side-agent" href="./?view=agent" target="_blank" data-action="agent-window">'+icon('window')+'<span>Interface chargé ↗</span></a><button data-action="settings" class="ghost" style="color:#a4b4cf;font-size:11px;justify-content:flex-start">'+icon('settings')+'<span>Paramètres & données</span></button><div class="side-note"><span class="live-dot"></span>Laboratoire de démonstration<br><br>Données fictives · stockage local</div></div></aside><section class="workspace"><header class="topbar"><div class="breadcrumb">Supervision internationale '+icon('chevron')+' <b>'+pageNames[view]+'</b></div><div class="top-actions"><span class="demo">DÉMONSTRATION</span><button class="ghost small" data-action="toggle-theme" aria-label="Activer le mode sombre" title="Mode sombre">'+icon('moon')+'</button><button class="ghost small" data-action="settings" title="Paramètres & données" aria-label="Paramètres & données">'+icon('settings')+'</button><div class="user"><span class="avatar">MC</span><div>Superviseur<small class="muted" style="display:block">Accès démo manager</small></div></div></div></header><main class="main"><div class="page-heading"><div><h1>'+pageNames[view]+'</h1><p>'+({map:'Vue internationale · ETR, bénéficiaires et transports',tvh:'Prise en charge, parcours et relivraison des véhicules',flux:'Concentrations, rapatriements et coopération entre équipes',cases:'Statuts, bénéficiaires et affectations',teams:'Affecter à un ou plusieurs chargés · disponibilités de l’équipe',dashboard:'Indicateurs calculés sur les dossiers de démonstration',archives:'Dossiers clôturés, conservés et réouvrables'}[view])+'</p></div><div class="actions"><button class="small" data-action="export">'+icon('download')+' Exporter</button><button class="small ghost" data-action="new">'+icon('plus')+' Ajouter</button><button class="primary" data-action="agent-window">'+icon('window')+' Interface chargé</button></div></div>'+ (storageError?'<div class="notice error">'+esc(storageError)+'</div>':'')+'<div id="content"></div><footer class="bottom-note"><span><span class="live-dot"></span>Stockage local à ce navigateur · aucune synchronisation entre appareils</span><span>72 scénarios initiaux · 24 pays · Horaires Europe/Paris</span></footer></main></section></div>';
}
function render(){
 if(map?.map)savedMapViewport={center:map.map.getCenter(),zoom:map.map.getZoom(),country:map.selectedCountry||'',region:map.selectedRegion?.properties.id||''};
 map?.destroy();map=null;availableRegions=[];
 if(view==='agent'){document.body.classList.remove('map-fullscreen');renderAgent();assignmentUI.refresh();return}
 $('#app').innerHTML=shell();$('#app').insertAdjacentHTML('beforeend',archiveZone());applyTheme(document.body.dataset.theme||'light');const rows=filtered(state,{...filters,tvh:view==='tvh'},view==='archives');let content='';
 if(['map','tvh','flux'].includes(view))content=renderMap(rows);
 if(view==='cases')content=renderCases(rows);
 if(view==='teams')content=renderTeams(rows);
 if(view==='dashboard')content=renderDashboard(rows);
 if(view==='archives')content=filterBar()+'<div class="notice">'+icon('success')+' Les dossiers archivés sont conservés avec leur historique. La réouverture les replace dans les vues actives.</div>'+caseTable(rows,true);
 $('#content').innerHTML=content;applyTheme(document.body.dataset.theme||'light');
 if(['map','tvh','flux'].includes(view)){
  map=new ControlMap($('#map'),{selectCountry:code=>{filters.country=code;filters.region=null;render()},selectRegion:region=>{filters.country=region.properties.country;filters.region=region;render()},openCase,
   onMessage:(msg,kind)=>{if(kind==='route'){if($('#route-message'))$('#route-message').textContent=msg}else toast(msg,kind==='error')},
   onViewportInfo:message=>{if($('#map-detail-hint'))$('#map-detail-hint').textContent=message},
   onRegionsReady:features=>{availableRegions=features;const select=$('#region-filter');if(!select)return;select.disabled=false;select.innerHTML=opt('','Toutes les régions / provinces',filters.region?.properties.id||'')+features.map(f=>opt(f.properties.id,f.properties.name,filters.region?.properties.id||'')).join('')}
  });
  map.update(state,rows,view,mapOptions());if(filters.country)map.focus(filters.country,filters.region);
  if(savedMapViewport&&savedMapViewport.country===filters.country&&savedMapViewport.region===(filters.region?.properties.id||''))map.map?.setView(savedMapViewport.center,savedMapViewport.zoom,{animate:false});
 }
 assignmentUI.refresh();
}
function mapDrilldown(){return '<div class="map-drilldown"><button class="small ghost" data-action="map-overview">'+icon('globe')+' Zone de supervision</button><select aria-label="Pays de supervision" data-filter="country">'+countryOptions(filters.country,true)+'</select>'+(view==='tvh'?'<small class="muted">Pays de départ ou d’arrivée · adresses facultatives</small>':'<select id="region-filter" aria-label="Région ou province" disabled><option>'+esc(filters.region?.properties.name||(filters.country?'Chargement des régions…':'Choisir d’abord un pays'))+'</option></select>'+(filters.region?'<button class="small ghost" data-action="clear-region">Tout le pays</button>':''))+'</div>'}
function renderMap(rows){
 const alerts=rows.filter(d=>priority(d,state.settings).key==='critical');
 const controls=view==='tvh'?'<button class="small" data-action="tvh-list">Procédures TVH</button><label class="check-line"><input type="checkbox" id="completed" '+(completed?'checked':'')+'> Livrés sur la carte</label>':view==='flux'?'<select id="flow-type" aria-label="Type de flux" style="width:140px;font-size:11px">'+opt('vehicles','Véhicules',flowType)+opt('people','Bénéficiaires',flowType)+'</select>':'<button class="small ghost" data-action="search-map">'+icon('search')+' Rechercher un lieu</button>';
 let out=kpis(rows)+filterBar()+(view==='tvh'?tvhSummary(rows):'')+'<div class="map-grid"><section class="panel map-shell"><div class="map-toolbar"><div class="segments"><button data-view="map" class="'+(view==='map'?'selected':'')+'">'+icon('map')+' Dossiers</button><button data-view="tvh" class="'+(view==='tvh'?'selected':'')+'">'+icon('truck')+' TVH</button><button data-view="flux" class="'+(view==='flux'?'selected':'')+'">'+icon('flow')+' Flux</button></div>'+'<div class="map-control-actions"><button class="small ghost" data-view="teams">'+icon('team')+' Équipes</button>'+controls+'<button class="small ghost" data-action="toggle-theme" aria-label="Activer le mode sombre" title="Mode sombre">'+icon(document.body.dataset.theme==='dark'?'sun':'moon')+'</button><button class="small" data-action="map-fullscreen" aria-pressed="'+mapFullscreen+'">'+icon('expand')+' '+(mapFullscreen?'Quitter le plein écran':'Plein écran')+'</button></div></div>'+mapDrilldown()+'<div id="map" class="map" aria-label="Carte interactive des dossiers ETR"></div><div class="map-caption"><div class="legend">'+Object.entries(PRIORITIES).map(([k,p])=>'<span><i class="dot '+k+'"></i>'+p.label+'</span>').join('')+(view==='tvh'?'<span><i class="dot transit"></i>TVH en cours</span><span><i class="dot tvh-pink"></i>TVH livré</span>':'')+'</div><span>'+(filters.country?country(filters.country).name+' · filtre actif':'Zone Europe · Maghreb · Turquie')+'</span></div><div id="map-detail-hint" class="map-detail-hint" aria-live="polite"></div></section><aside class="panel attention"><div class="panel-header"><h2>Dossiers critiques</h2><span class="attention-count">'+alerts.length+'</span></div><div class="critical-number-list">'+alerts.map(d=>'<button class="critical-number" data-open="'+esc(d.id)+'">'+esc(d.id)+'</button>').join('')+(!alerts.length?'<div class="empty">Aucun dossier critique</div>':'')+'</div></aside></div>';
 if(view==='tvh')out+='<div class="notice" id="route-message">TVH : KSK violet en cours · rose livré. Départ et arrivée suivis au pays par défaut ; adresses facultatives. Liaisons schématiques, aucun suivi GPS.</div>';
 if(view==='flux')out+='<div class="notice">Les liens de flux sont schématiques. Ils ne constituent ni un itinéraire ni une décision logistique.</div>'+flowPanels(rows);
 const unlocated=view==='tvh'?[]:rows.filter(d=>!hasPoint(d.location));if(unlocated.length)out+='<div class="notice warn">'+unlocated.length+' dossier(s) sans position confirmée, accessibles dans DOSSIERS : '+unlocated.map(d=>'<button class="link-button" data-open="'+esc(d.id)+'">'+esc(d.id)+'</button>').join(', ')+'</div>';
 if(view==='tvh')out+='<section class="panel below"><div class="panel-header"><h2>Procédures TVH</h2></div>'+tvhTable(rows)+'</section>';
 return out+'<section class="panel below"><div class="panel-header"><h2>Répartition de l’équipe</h2><button class="small ghost" data-view="teams">Voir les affectations '+icon('chevron')+'</button></div><div class="team-strip">'+state.agents.slice(0,4).map(a=>{const n=rows.filter(d=>hasAssignee(d,a.id)).length,av=engineAvailability(a,new Date(),state.engine);return '<div class="team-summary"><div class="team-line"><b>'+esc(a.name)+'</b><span class="'+(av.ok?'available':'unavailable')+'">'+av.label+'</span></div><div class="progress-track"><div class="progress-fill" style="width:'+Math.min(100,n/a.capacity*100)+'%"></div></div><div class="team-line muted"><span>'+n+' dossiers / repère '+a.capacity+'</span><span>'+a.languages.map(l=>l.toUpperCase()).join(' · ')+'</span></div></div>'}).join('')+'</div></section>';
}
function caseTable(rows,archived=false){return '<section class="panel"><div class="panel-header"><h2>'+rows.length+' dossier'+(rows.length>1?'s':'')+'</h2><span class="muted" style="font-size:10px">Cliquez pour consulter · glissez un dossier terminé vers le classeur</span></div><div class="table-wrap"><table><thead><tr><th>DOSSIER</th><th>PAYS / LIEU</th><th>PRIORITÉ</th><th>VÉHICULE / TVH</th><th>BÉNÉFICIAIRES</th><th>CHARGÉS</th><th>'+(archived?'CLÔTURE':'SITUATION')+'</th><th></th></tr></thead><tbody>'+rows.map(d=>'<tr '+(!archived?'data-case="'+esc(d.id)+'"':'')+'><td><button class="link-button" data-open="'+esc(d.id)+'">'+esc(d.id)+'</button><small class="muted" style="display:block">'+d.type+' · '+age(d)+'</small></td><td>'+country(d.country).flag+' '+country(d.country).name+'<small class="muted" style="display:block">'+esc(d.location?.label.split(' — ')[0]||'Non localisé')+'</small></td><td>'+badge(d)+'</td><td>'+d.stage+'<small class="muted" style="display:block">TVH · '+d.tvh+'</small></td><td>'+people(d)+' pers. '+(waiting(d)?'<span class="priority-badge urgent">En attente</span>':'')+'<small class="muted" style="display:block">'+esc(d.groups.length>1?d.groups.length+' sous-groupes':d.groups[0].status)+'</small></td><td><button class="link-button" data-action="choose-assignees" data-id="'+esc(d.id)+'">'+esc(assignedNames(d))+'</button></td><td>'+(archived?date(d.closed):ready(d)?'<span class="priority-badge normal">Terminé</span>':'En cours')+'</td><td><button class="small ghost" data-action="'+(archived?'reopen':'archive')+'" data-id="'+esc(d.id)+'" aria-label="'+(archived?'Réouvrir':'Archiver')+' '+esc(d.id)+'">'+icon(archived?'plus':'archive')+'</button></td></tr>').join('')+'</tbody></table></div>'+(!rows.length?'<div class="empty">Aucun dossier ne correspond aux filtres.</div>':'')+'</section>'}

function card(d,agentId=''){return '<article class="case-card '+(ready(d)?'case-ready':'')+'" data-case="'+esc(d.id)+'" tabindex="0"><div class="row"><button class="link-button" data-open="'+esc(d.id)+'">'+esc(d.id)+'</button><span class="actions">'+badge(d)+(agentId&&agentId!==(d.initialAgent||d.agent)?'<button class="remove-assignment" data-action="remove-assignee" data-id="'+esc(d.id)+'" data-agent="'+esc(agentId)+'" aria-label="Retirer '+esc(agentName(agentId))+' du dossier '+esc(d.id)+'">×</button>':'')+'</span></div><p>'+country(d.country).flag+' '+esc(d.location?.label.split(' — ')[0]||country(d.country).name)+'</p><small>'+esc(d.stage)+(d.tvh!=='Non applicable'?' · '+d.tvh:'')+'</small><div class="card-bottom">'+(ready(d)?'<span class="ready-tag">'+icon('check')+' Terminé</span>':'<span class="muted">'+people(d)+' bénéficiaire(s)</span>')+(assigneeIds(d).length>1?'<span class="shared-tag">'+icon('team')+' '+assigneeIds(d).length+' chargés</span>':'')+'</div></article>'}

function archiveZone(){return '<button class="archive-classer drop" data-drop="archive" data-action="view-archives" aria-label="Classeur des archives : déposer un dossier terminé ou ouvrir les archives"><svg class="archive-folder" viewBox="0 0 76 58" aria-hidden="true"><path d="M5 15V8a4 4 0 0 1 4-4h20l8 8h29a5 5 0 0 1 5 5v31H5z" fill="#d4eadd" stroke="#62a589" stroke-width="2"/><path d="M3 21a4 4 0 0 1 4-4h61a4 4 0 0 1 4 5l-6 29H8z" fill="#e9f7ef" stroke="#62a589" stroke-width="2"/><circle cx="57" cy="39" r="12" fill="#208a64"/><path d="m51 39 4 4 8-9" stroke="white" stroke-width="2.5" fill="none" stroke-linecap="round"/></svg><span><strong>Archives <small>'+state.cases.filter(d=>d.archived).length+'</small></strong><span class="archive-hint">Glisser un dossier terminé ici</span><span class="archive-release">Relâcher pour archiver</span></span></button>'}

function renderCases(rows){return filterBar()+'<div class="actions" style="margin-bottom:16px"><div class="segments"><button data-action="cases-list" class="'+(dossierMode==='list'?'selected':'')+'">Liste</button><button data-action="cases-kanban" class="'+(dossierMode==='kanban'?'selected':'')+'">Vue par statut</button></div><span class="muted" style="font-size:11px">Les bénéficiaires conservent leur suivi propre.</span></div>'+(dossierMode==='list'?caseTable(rows):'<div class="kanban">'+STAGES.map(s=>'<section class="kan-col drop" data-drop="stage" data-stage="'+s+'"><div class="col-title">'+s+' <span class="tag">'+rows.filter(d=>d.stage===s).length+'</span></div>'+rows.filter(d=>d.stage===s).map(d=>card(d)).join('')+'</section>').join('')+'</div>')}
function renderTeams(rows){const list=state.agents.filter(a=>a.name.toLowerCase().includes(agentQuery.toLowerCase())&&(!agentLanguage||a.languages.includes(agentLanguage))&&(!agentService||a.service===agentService)&&(!agentAvailability||(engineAvailability(a,new Date(),state.engine).ok?'yes':'no')===agentAvailability));
 return filterBar()+'<div class="actions" style="margin-bottom:16px"><div class="segments"><button data-engine="overview" class="'+(teamMode==='overview'?'selected':'')+'">Synthèse</button><button data-action="teams-assign" class="'+(teamMode==='assign'?'selected':'')+'">Affectations</button><button data-action="teams-planning" class="'+(teamMode==='planning'?'selected':'')+'">Planning</button></div></div><div class="filters"><input id="agent-query" value="'+esc(agentQuery)+'" placeholder="Nom du collaborateur" aria-label="Nom du collaborateur"><select id="agent-language" aria-label="Langue du collaborateur">'+opt('','Toutes les langues',agentLanguage)+Object.entries(LANGUAGES).map(([k,v])=>opt(k,v,agentLanguage)).join('')+'</select><select id="agent-availability" aria-label="Disponibilité du collaborateur">'+opt('','Toute disponibilité',agentAvailability)+opt('yes','Disponibles',agentAvailability)+opt('no','Indisponibles',agentAvailability)+'</select><select id="agent-service" aria-label="Service du collaborateur">'+opt('','Tous les services',agentService)+[...new Set(state.agents.map(a=>a.service))].map(v=>opt(v,v,agentService)).join('')+'</select><button class="small" data-action="import-planning">'+icon('upload')+' Import planning</button><button class="small ghost" data-action="planning-template">Modèle CSV</button></div>'+(teamMode==='overview'?assignmentUI.overview(list,rows,filtered(state,filters,true)):teamMode==='planning'?renderPlanning(list,rows):'<div class="teams-board"><section class="unassigned drop" data-drop="assign" data-agent=""><div class="col-title">Non affectés <span class="tag">'+rows.filter(d=>!assigneeIds(d).length).length+'</span></div>'+rows.filter(d=>!assigneeIds(d).length).map(d=>card(d)).join('')+'</section><div class="agents-grid">'+list.map(a=>{const assigned=rows.filter(d=>hasAssignee(d,a.id)),total=active(state).filter(d=>hasAssignee(d,a.id)).length,av=engineAvailability(a,new Date(),state.engine);return '<section class="agent-card drop" data-drop="assign" data-agent="'+a.id+'"><header><span class="avatar">'+a.name.split(' ').map(w=>w[0]).join('')+'</span><div><h3>'+esc(a.name)+'</h3><span class="'+(av.ok?'available':'unavailable')+'">'+av.label+'</span></div></header><div class="tags">'+a.languages.map(l=>'<span class="tag">'+LANGUAGES[l]+'</span>').join('')+'</div><span class="muted" style="font-size:10px">'+esc(a.service)+'</span><div class="load-line"><span>'+total+' dossiers actifs</span><span>Capacité indicative '+a.capacity+'</span></div><div class="progress-track"><div class="progress-fill" style="width:'+Math.min(100,total/a.capacity*100)+'%;background:'+(total>a.capacity?'#db9019':'')+'"></div></div><div class="agent-dossiers">'+assigned.map(d=>card(d,a.id)).join('')+(!assigned.length?'<small class="muted">Glissez ici pour ajouter ce chargé</small>':'')+'</div><button class="ghost small" data-action="edit-agent" data-id="'+a.id+'">Profil & langues</button></section>'}).join('')+'</div></div>')+'<div class="notice">Glisser un dossier ajoute le chargé à ses affectations. Le responsable initial est conservé. Un relais peut être ajouté ; les tâches se réaffectent séparément. Chaque affectation est vérifiée par le moteur.</div>';
}
function shiftBar(sh){if(!sh||sh.unavailable)return '<span class="muted">'+esc(sh?.reason||'Non renseigné')+'</span>';const p=t=>{const [h,m]=t.split(':').map(Number);return(h+m/60)/24*100},a=p(sh.start),b=p(sh.end),bs=p(sh.breakStart),be=p(sh.breakEnd);return '<div class="shift-bar">'+(b<a?'<span class="shift-time" style="left:0;width:'+b+'%"></span><span class="shift-time" style="left:'+a+'%;right:0"></span>':'<span class="shift-time" style="left:'+a+'%;width:'+(b-a)+'%"></span>')+'<span class="break-time" style="left:'+bs+'%;width:'+Math.max(0,be-bs)+'%"></span></div>'}
function renderPlanning(list,rows){const loads=workloadIndex(state,state.engine,new Date());return '<section class="panel"><div class="planning-tools"><label class="field">Journée de prise de poste<input type="date" id="planning-date" value="'+planningDate+'"></label><span class="muted" style="font-size:11px;align-self:center">Bleu : service · Jaune : pause · Cliquez sur Modifier pour corriger une journée.</span></div><div class="table-wrap"><table class="calendar"><thead><tr><th>COLLABORATEUR</th><th>00h</th><th colspan="2">06h — 12h — 18h — 24h</th><th>HORAIRES / PAUSE</th><th>DOSSIERS</th><th></th></tr></thead><tbody>'+list.map(a=>{const sh=a.schedule.find(s=>s.date===planningDate),mine=rows.filter(d=>hasAssignee(d,a.id)),points=loads.get(a.id).weighted;return '<tr><td><b>'+esc(a.name)+'</b><small class="muted" style="display:block">'+esc(a.service)+'</small></td><td colspan="3" style="min-width:230px">'+shiftBar(sh)+'</td><td>'+(sh&&!sh.unavailable?sh.start+' – '+sh.end+'<small class="muted" style="display:block">Pause '+sh.breakStart+' – '+sh.breakEnd+'</small>':'Repos / non renseigné')+'</td><td>'+mine.length+' dossiers · '+points+' de charge pondérée</td><td><button class="small ghost" data-action="edit-shift" data-id="'+a.id+'">Modifier</button></td></tr>'}).join('')+'</tbody></table></div></section>'}
function flowPanels(rows){const groups=new Map();rows.filter(d=>d.tvh==='En attente'||d.tvh==='En cours').forEach(d=>{const journey=tvhJourney(d);const key=journey.originCountry+'>'+journey.destinationCountry;const list=groups.get(key)||[];list.push(d);groups.set(key,list)});
 const mutual=[...groups].filter(([,list])=>list.length>1);const cooperation=COUNTRIES.map(c=>{const ds=rows.filter(d=>d.country===c.code),needs=[...new Set(ds.map(d=>d.language))];return {c,ds,needs}}).filter(x=>x.ds.length);
 return '<div class="dashboard-grid below"><section class="panel"><div class="panel-header"><h2>Possibilités de mutualisation</h2><span class="tag">À vérifier</span></div>'+(mutual.length?mutual.map(([,ds])=>'<div class="flow-item"><b>'+country(tvhJourney(ds[0]).originCountry).flag+' '+country(tvhJourney(ds[0]).originCountry).name+' → '+esc(country(tvhJourney(ds[0]).destinationCountry)?.name||'Destination à confirmer')+'</b><p>'+ds.map(d=>'<button class="link-button" data-open="'+d.id+'">'+d.id+'</button>').join(' · ')+'</p><small>Départs au sein du même pays : vérifier les villes, délais, capacités et destinations exactes avant toute organisation.</small></div>').join(''):'<div class="empty">Aucun groupe de départ / destination commun dans ce filtre.</div>')+'</section><section class="panel"><div class="panel-header"><h2>Coopération & langues réellement attribuées</h2></div>'+cooperation.map(({c,ds,needs})=>'<div class="flow-item"><b>'+c.flag+' '+c.name+' · '+ds.length+' dossiers</b>'+needs.map(l=>{const capable=state.agents.filter(a=>a.languages.includes(l)),av=capable.filter(a=>engineAvailability(a,new Date(),state.engine).ok);return '<small>'+LANGUAGES[l]+' : '+av.length+' disponible(s) / '+capable.length+' compétent(s)'+(av.length?' · '+av.map(a=>esc(a.name)).join(', '):' · relais linguistique à organiser')+'</small>'}).join('')+'</div>').join('')+'</section></div>';
}
function bars(entries,total,color='#4c89ef'){return entries.map(([label,n])=>'<div class="bar-row"><span>'+esc(label)+'</span><div class="progress-track"><div class="progress-fill" style="width:'+(n/Math.max(1,total)*100)+'%;background:'+color+'"></div></div><b>'+n+'</b></div>').join('')}
function renderDashboard(rows){
 const perCountry=COUNTRIES.map(c=>[c.flag+' '+c.name,rows.filter(d=>d.country===c.code).length]).filter(x=>x[1]).sort((a,b)=>b[1]-a[1]);
 const perAgent=state.agents.map(a=>[a.name,rows.filter(d=>hasAssignee(d,a.id)).length]);perAgent.push(['Non affectés',rows.filter(d=>!assigneeIds(d).length).length]);
 return kpis(rows)+filterBar()+'<div class="dashboard-grid"><section class="panel"><div class="panel-header"><h2>Statuts des véhicules</h2></div><div class="chart">'+bars(STAGES.map(stage=>[stage,rows.filter(d=>d.stage===stage).length]),rows.length)+'</div></section><section class="panel"><div class="panel-header"><h2>Priorités & bénéficiaires</h2></div><div class="chart">'+Object.entries(PRIORITIES).map(([k,p])=>bars([[p.label,rows.filter(d=>priority(d,state.settings).key===k).length]],rows.length,p.color)).join('')+'<div class="notice">Bénéficiaires en attente : <b>'+rows.filter(waiting).length+'</b> dossiers · TVH en attente : <b>'+rows.filter(d=>d.tvh==='En attente').length+'</b> · Archives : <b>'+filtered(state,filters,true).length+'</b></div></div></section><section class="panel"><div class="panel-header"><h2>Dossiers par pays</h2></div><div class="chart">'+bars(perCountry,Math.max(...perCountry.map(x=>x[1]),1))+'</div></section><section class="panel"><div class="panel-header"><h2>Dossiers par chargé</h2></div><div class="chart">'+bars(perAgent,Math.max(...perAgent.map(x=>x[1]),1))+'<small class="muted">Un dossier partagé apparaît pour chacun des chargés concernés.</small></div></section></div>'+flowPanels(rows);
}

function showModal(html,onMount){$('#modal-root').innerHTML='<div class="modal-shade"><section class="modal" role="dialog" aria-modal="true">'+html+'</section></div>';modalClose=null;onMount?.();setTimeout(()=>$('input,button,select',$('#modal-root'))?.focus(),0)}
function closeModal(){const cb=modalClose;$('#modal-root').innerHTML='';modalClose=null;cb?.()}
function confirmAction(title,description,callback){showModal('<h2>'+esc(title)+'</h2><p>'+esc(description)+'</p><div class="actions"><button data-action="close-modal">Annuler</button><button class="primary" id="confirm-action">Confirmer</button></div>',()=>{$('#confirm-action').onclick=()=>{closeModal();callback()}})}

function closeDrawer(){$('#drawer-root').innerHTML='';selected=null;editing=null}
function openCase(id){const d=state.cases.find(d=>d.id===id);if(!d)return;if(view==='agent'){agentLoadedId=d.id;agentEditing=structuredClone(d);draftRevision=storageRevision;renderAgent();return}selected=id;editing=structuredClone(d);drawerMode='view';draftRevision=storageRevision;renderDrawer()}
function locationField(d,key,label){const p=d[key];return '<div class="location-field"><div><b style="font-size:11px">'+label+'</b><button type="button" class="small ghost" data-action="locate" data-field="'+key+'">'+icon('search')+' Localiser</button></div><p>'+esc(p?.label||'Non renseigné')+'</p><small>'+esc(hasPoint(p)?p.lat.toFixed(5)+', '+p.lng.toFixed(5)+' · '+(p.source||'Position confirmée'):'Sans coordonnées confirmées')+'</small></div>'}
function beneficiaryFlags(g){return (g.vulnerable?'<span class="beneficiary-flag vulnerable">'+icon('shield')+' Personnes vulnérables</span>':'')+(g.animals?'<span class="beneficiary-flag animals">'+icon('pet')+' Animaux</span>':'')}
function groupForm(d,compact=false){return '<div class="beneficiary-composition">'+d.groups.map((g,i)=>'<div class="group-box" data-group="'+i+'">'+(!compact||d.groups.length>1?'<div class="actions"><input aria-label="Nom du groupe '+(i+1)+'" name="g'+i+'_name" value="'+esc(g.name)+'" style="flex:1">'+(d.groups.length>1?'<button type="button" class="small ghost" data-action="remove-group" data-index="'+i+'" aria-label="Retirer le groupe '+(i+1)+'">'+icon('close')+'</button>':'')+'</div>':'<div class="mini-group-title">Bénéficiaires</div>')+'<div class="group-numbers">'+[['adults','Adultes'],['children','Enfants']].map(([k,label])=>'<label>'+icon(k==='children'?'child':'person')+label+'<input aria-label="'+label+' groupe '+(i+1)+'" name="g'+i+'_'+k+'" type="number" min="0" max="1000" value="'+(k==='adults'?adultCount(g):g.children)+'"></label>').join('')+'</div><div class="beneficiary-indicators"><label class="beneficiary-flag vulnerable"><input type="checkbox" name="g'+i+'_vulnerable" '+(g.vulnerable?'checked':'')+'>'+icon('shield')+' Personnes vulnérables</label><label class="beneficiary-flag animals"><input type="checkbox" name="g'+i+'_animals" '+(g.animals?'checked':'')+'>'+icon('pet')+' Animaux</label></div>'+select('Situation des bénéficiaires','g'+i+'_status',options(BENEFIT_OPTIONS,g.status))+'</div>').join('')+'<small class="muted">Le total compte les adultes et les enfants. Vulnérabilité et animaux sont des indicateurs séparés.</small>'+(compact?'<div class="agent-person-total" id="agent-person-total">'+people(d)+' personne(s)</div>':'')+'</div>'}
function renderDrawer(){
 if(!editing)return;const d=editing;if(drawerMode==='tvh'){renderTVHDrawer(d);return}const editingMode=drawerMode==='edit';
 const summary='<div class="case-summary-grid"><div><span>Véhicule</span><strong>'+esc(d.stage)+'</strong></div><div><span>Transport TVH</span><strong>'+esc(d.tvh)+'</strong></div><div><span>Bénéficiaires</span><strong>'+people(d)+' personne(s)</strong></div><div><span>Pays</span><strong>'+country(d.country).flag+' '+country(d.country).name+'</strong></div></div>'+caseSignalSummary(d)+'<div class="tvh-case-link">'+(d.tvh!=='Non applicable'?tvhStatusBadge(d.tvh):'')+(!d.archived?'<button class="small" data-action="tvh-edit" data-id="'+esc(d.id)+'">'+(d.tvh==='Non applicable'?'Ajouter un TVH':'Procédure TVH')+'</button>':'')+'</div><div class="section-title">Chargés affectés <button class="small" data-action="choose-assignees" data-id="'+esc(d.id)+'">'+icon('team')+' Affecter</button></div><div class="assignment-chips">'+(assigneeIds(d).length?assigneeIds(d).map(id=>'<span class="assignment-chip">'+esc(agentName(id))+(id===(d.initialAgent||d.agent)?' · Responsable initial':' · Complément')+(id!==(d.initialAgent||d.agent)?'<button data-action="remove-assignee" data-id="'+esc(d.id)+'" data-agent="'+esc(id)+'" aria-label="Retirer '+esc(agentName(id))+'">×</button>':'')+'</span>').join(''):'<span class="muted">Non affecté</span>')+'</div><div class="section-title">Situation des bénéficiaires</div>'+d.groups.map(g=>'<div class="beneficiary-summary"><b>'+esc(g.name)+'</b><span>'+esc(g.status)+'</span><small>'+adultCount(g)+' adulte(s) · '+g.children+' enfant(s)'+'</small>'+beneficiaryFlags(g)+'</div>').join('')+'<div class="section-title">Localisation</div>'+[['location','Immobilisation'],['depot','Dépôt / garage'],['destination','Relivraison véhicule'],['beneficiaryDestination','Destination des bénéficiaires']].map(([key,label])=>'<div class="summary-location"><b>'+label+'</b><p>'+esc(d[key]?.label||'Non renseigné')+'</p></div>').join('')+(d.notes?'<div class="section-title">Commentaires</div><p class="summary-notes">'+esc(d.notes)+'</p>':'');
 const editForm='<form id="detail-form"><div class="section-title">Informations du dossier</div><div class="form-grid">'+select('Pays','country',countryOptions(d.country))+select('Assistance','type',options(['Panne','Accident'],d.type))+select('Statut du véhicule','stage',options(STAGES,d.stage))+select('Transport de véhicule','tvh',options(TVH,d.tvh))+'</div><div class="section-title">Localisation</div><div style="display:grid;gap:9px">'+locationField(d,'location','Lieu d’immobilisation')+locationField(d,'depot','Dépôt / garage')+locationField(d,'destination','Relivraison du véhicule')+locationField(d,'beneficiaryDestination','Destination des bénéficiaires')+'</div><div class="section-title">Bénéficiaires <button type="button" class="small ghost" data-action="add-group">'+icon('plus')+' Sous-groupe</button></div>'+groupForm(d)+'<div class="section-title">Affectations</div><label class="field">Chargés concernés<select name="assignees" multiple size="4">'+state.agents.map(a=>'<option value="'+a.id+'" '+(hasAssignee(d,a.id)?'selected':'')+'>'+esc(a.name)+'</option>').join('')+'</select></label>'+select('Langue requise','language',Object.entries(LANGUAGES).map(([k,v])=>opt(k,v,d.language)).join(''))+'<details class="priority-options"><summary>Priorité de supervision</summary><div class="form-grid">'+select('Attribution','priorityMode',opt('auto','Automatique',d.priorityMode)+opt('manual','Manuelle',d.priorityMode))+select('Niveau manuel','priority',Object.entries(PRIORITIES).map(([k,p])=>opt(k,p.label,d.priority)).join(''))+'</div>'+'</details><label class="field">Commentaires<textarea name="notes">'+esc(d.notes)+'</textarea></label></form>';
 $('#drawer-root').innerHTML='<div class="drawer-shade" data-action="close-drawer"></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="Dossier '+esc(d.id)+'"><header class="drawer-head"><div><div class="eyebrow">Dossier ETR · '+(d.archived?'Archivé':'Supervision')+'</div><h1>'+esc(d.id)+'</h1><small class="muted">'+date(d.opened)+' · '+age(d)+'</small></div><div class="actions">'+badge(d)+'<button class="ghost" data-action="close-drawer" aria-label="Fermer la fiche">'+icon('close')+'</button></div></header><div class="drawer-body">'+(editingMode?editForm:summary+assignmentUI.taskRows(d.id))+'<details class="history-details"><summary>Historique · '+d.history.length+' événement(s)</summary><div class="history">'+[...d.history].reverse().map(h=>'<div class="history-item"><small>'+date(h.at)+'</small>'+esc(h.text)+'</div>').join('')+'</div></details></div><footer class="drawer-foot"><button data-action="'+(d.archived?'reopen':'archive')+'" data-id="'+esc(d.id)+'">'+icon(d.archived?'plus':'archive')+' '+(d.archived?'Réouvrir':'Archiver')+'</button>'+(editingMode?'<button data-action="cancel-case-edit">Annuler</button><button class="primary" data-action="save-case">'+icon('check')+' Enregistrer</button>':'<button data-action="edit-case">Modifier les informations</button><button class="primary" data-action="close-drawer">Fermer</button>')+'</footer></aside>';
}

function fromParis(v){if(!v)return null;const raw=new Date(v+'Z');let result=raw;for(let i=0;i<2;i++){const parts=isoLocal(result);const difference=Date.parse(parts+'Z')-Date.parse(v+'Z');result=new Date(+result-difference)}return result.toISOString()}
function readForm(d,form){const priorCountry=d.country,f=new FormData(form);for(const k of ['country','type','stage','tvh','agent','language','priorityMode','priority','priorityReason','notes'])if(f.has(k)&&!(k==='country'&&!f.get(k)))d[k]=String(f.get(k));if(d.country!==priorCountry&&d.tvhOriginPrecision==='country'&&d.tvhOriginCountry===priorCountry)d.tvhOriginCountry=d.country;if(form.id==='detail-form'){const ids=f.getAll('assignees');d.agent=ids[0]||'';d.associates=ids.slice(1)}normaliseSignals(d);for(const signal of PRIORITY_SIGNALS)if(form.querySelector('[name="signal_'+signal.key+'"]'))d.signals[signal.key]=f.has('signal_'+signal.key);d.groups=d.groups.map((g,i)=>{const n={...g};for(const k of ['adults','children'])if(f.has('g'+i+'_'+k))n[k]=Number(f.get('g'+i+'_'+k));for(const k of ['vulnerable','animals'])if(form.querySelector('[name="g'+i+'_'+k+'"]'))n[k]=f.has('g'+i+'_'+k);for(const k of ['name','status'])if(f.has('g'+i+'_'+k))n[k]=String(f.get('g'+i+'_'+k));return n});return d;}

function capture(){if(view==='agent'&&agentEditing&&$('#agent-form')){readForm(agentEditing,$('#agent-form'));agentEditing.id=normalizeId($('#agent-id').value);}else if(editing&&$('#tvh-form'))readTVHForm(editing,$('#tvh-form'));else if(editing&&$('#detail-form'))readForm(editing,$('#detail-form'))}
function persistDraft(d,isNew=false,assignmentOverride=false){
 try{if(view==='agent'&&d.country==='FR')throw Error('Choisissez le pays ETR à l’étranger. La France est la destination du TVH.');const original=state.cases.find(x=>x.id===normalizeId(d.id));if(draftRevision!==storageRevision&&!isNew)throw Error('Les données ont changé dans une autre fenêtre. Rouvrez le dossier avant de sauvegarder.');if(isNew&&original)throw Error('Ce dossier est déjà enregistré.');
 if(!assignmentOverride&&!assignmentUI.validateDraft(d,()=>persistDraft(d,isNew,true)))return;
 const candidate=structuredClone(d);candidate.id=normalizeId(candidate.id);delete candidate.action;delete candidate.due;delete candidate.actionOwner;
 if(!people(candidate))throw Error('Renseignez au moins un bénéficiaire.');if(candidate.priorityMode==='manual')candidate.priorityReason='Priorité définie manuellement';
 validateState({...structuredClone(state),cases:[...state.cases.filter(x=>x.id!==candidate.id),candidate]});const next=structuredClone(state);let target=next.cases.find(x=>x.id===candidate.id);if(!target){target=createCase(next,{id:candidate.id,country:candidate.country,type:candidate.type});candidate.opened=target.opened}
 const prior={stage:target.stage,tvh:target.tvh,groups:JSON.stringify(target.groups),ids:assigneeIds(target),priority:priority(target,next.settings),history:target.history,signals:{...target.signals}};const wanted=assigneeIds(candidate);Object.assign(target,candidate);target.history=prior.history;target.agent=prior.ids[0]||'';target.associates=prior.ids.slice(1);const warnings=setAssignees(next,target,wanted);
 for(const signal of PRIORITY_SIGNALS)if(Boolean(prior.signals[signal.key])!==Boolean(target.signals?.[signal.key]))record(target,'Signalement '+(target.signals[signal.key]?'activé':'retiré')+' : '+signal.label);if(prior.stage!==target.stage)record(target,'Statut véhicule : '+prior.stage+' → '+target.stage);if(prior.tvh!==target.tvh)record(target,'TVH : '+prior.tvh+' → '+target.tvh);if(prior.groups!==JSON.stringify(target.groups))record(target,'Bénéficiaires : '+target.groups.map(g=>g.name+' — '+g.status).join(' ; '));const after=priority(target,next.settings);if(after.key!==prior.priority.key)record(target,'Priorité : '+PRIORITIES[prior.priority.key].label+' → '+PRIORITIES[after.key].label+' · '+after.reason);if(assignmentOverride)record(target,'Dérogation d’affectation confirmée explicitement par le manager');record(target,'Informations du dossier actualisées');validateState(next);state=next;closeDrawer();if(view==='agent'){agentLoadedId=target.id;agentEditing=structuredClone(target)}commit('Dossier '+target.id+' enregistré'+(warnings.length?' · '+warnings.slice(0,2).join(' · '):''));draftRevision=storageRevision;
 }catch(e){toast(e.message,true)}
}

function locate(key,mapOnly=false){capture();const d=view==='agent'?agentEditing:editing;const current=d?.[key];showModal('<h2>'+ (mapOnly?'Rechercher sur la carte':'Localiser et confirmer')+'</h2><p>Adresse, nom d’établissement ou GPS « latitude, longitude ». La recherche externe se lance uniquement avec le bouton Rechercher.</p><form id="place-form"><label class="field">Pays<select id="place-country">'+countryOptions((key==='destination'?d?.tvhDestinationCountry:key==='depot'?d?.tvhOriginCountry:d?.country)||filters.country||'',true)+'</select></label><label class="field">Lieu<input id="place-query" placeholder="Adresse, établissement ou 48.8566, 2.3522" value="'+esc(current?.label||'')+'" autocomplete="off"></label><button class="primary" type="submit">'+icon('search')+' Rechercher</button></form><div id="place-status" class="muted" style="font-size:11px;margin-top:12px"></div><div id="place-results" class="results"></div><div class="actions">'+(!mapOnly?'<button id="unlocated">Conserver comme non localisé</button>':'')+'<button data-action="close-modal">Fermer</button></div>',()=>{
 let resultSet=[];const choose=p=>{try{if(mapOnly){map?.map?.setView([p.lat,p.lng],15);if(window.L&&map?.map)L.popup().setLatLng([p.lat,p.lng]).setContent(esc(p.label)).openOn(map.map)}else{confirmTVHPlace(d,key,p);if(p.country&&key==='location'&&COUNTRIES.some(c=>c.code===p.country))d.country=p.country;view==='agent'?renderAgent():renderDrawer()}closeModal();toast(mapOnly?'Lieu affiché':'Emplacement confirmé')}catch(e){toast(e.message,true)}};
 $('#place-form').onsubmit=async e=>{e.preventDefault();const btn=$('button[type=submit]',$('#place-form'));btn.disabled=true;$('#place-status').textContent='Recherche en cours…';try{resultSet=await searchPlace($('#place-query').value,$('#place-country').value);$('#place-results').innerHTML=resultSet.map((p,i)=>'<button class="result" data-result="'+i+'">'+esc(p.label)+'<small>'+p.lat.toFixed(5)+', '+p.lng.toFixed(5)+' · '+esc(p.source)+' · Cliquer pour confirmer</small></button>').join('');$('#place-status').textContent=resultSet.length+' résultat(s) à confirmer';$$('[data-result]').forEach(b=>b.onclick=()=>choose(resultSet[+b.dataset.result]))}catch(e){$('#place-status').textContent=e.message;$('#place-results').innerHTML=''}finally{btn.disabled=false}};
 if($('#unlocated'))$('#unlocated').onclick=()=>{const q=$('#place-query').value.trim();if(!q){toast('Saisissez le lieu à conserver.',true);return}const place={label:q,lat:null,lng:null,country:$('#place-country').value||d.country,source:'Texte saisi · non localisé'};try{confirmTVHPlace(d,key,place)}catch(e){toast(e.message,true);return}closeModal();view==='agent'?renderAgent():renderDrawer();toast('Lieu conservé sans coordonnées')};
 })}
function defaultAgentDraft(){const temporary={cases:[]},d=createCase(temporary,{id:'NEW',country:'ES'});d.id='';return d}
function agentCountryOptions(current){return (current==='FR'?'<option value="" selected disabled>Choisir le pays ETR à l’étranger</option>':'')+COUNTRIES.filter(c=>c.code!=='FR').map(c=>opt(c.code,c.flag+' '+c.name,current)).join('')}
function agentAssignmentBanner(id){const d=state.cases.find(d=>d.id===normalizeId(id||''));return '<section class="agent-assignment-banner"><small>CHARGÉS AFFECTÉS AU DOSSIER</small>'+(d&&assigneeIds(d).length?'<div class="agent-assignment-names">'+assigneeIds(d).map(a=>'<span><b>'+esc(agentName(a))+'</b><small>'+(a===(d.initialAgent||d.agent)?'Responsable initial':'Chargé complémentaire')+'</small></span>').join('')+'</div>':'<p>Aucun chargé affecté · attribution par le manager</p>')+'</section>'}
function renderAgent(){
 if(!agentEditing)agentEditing=defaultAgentDraft();const d=agentEditing,isExisting=agentLoadedId===d.id,criticalOnly=d.priorityMode==='manual'&&d.priority==='critical';
 const stages=AGENT_STAGES.includes(d.stage)?AGENT_STAGES:[d.stage,...AGENT_STAGES];
 $('#app').innerHTML='<main class="agent-page"><div class="brand"><div class="brand-symbol" style="color:white">'+icon('chart')+'</div><div><b>Manager Control</b><small class="muted" style="display:block">Interface chargé · démonstration</small></div></div><div id="agent-assignees">'+agentAssignmentBanner(d.id)+'</div><div class="agent-title-row"><h1>Saisie rapide</h1><button class="small ghost" data-action="toggle-theme" aria-label="Activer le mode sombre">'+icon(document.body.dataset.theme==='dark'?'sun':'moon')+'</button></div><div class="panel"><div class="panel-content"><form id="agent-form"><label class="field">Numéro de dossier<div class="inline-search"><input id="agent-id" name="id" value="'+esc(d.id)+'" placeholder="Ex. 826431" required autocomplete="off"><button type="button" data-action="find-agent-case" aria-label="Retrouver le dossier">'+icon('search')+'</button></div></label><div id="duplicate">'+(isExisting?'Dossier existant ouvert pour mise à jour.':'')+'</div><button type="button" class="small critical-flag" data-action="agent-critical" aria-pressed="'+criticalOnly+'">'+icon('shield')+' '+(criticalOnly?'Dossier critique ✓':'Signaler comme critique')+'</button>'+agentSignalsForm(d)+(criticalOnly?'<details class="critical-optional"><summary>Compléter les informations si nécessaire</summary>':'')+'<div class="form-grid" style="margin-top:12px">'+select('Pays ETR · hors France','country',agentCountryOptions(d.country),'required')+select('Assistance','type',options(['Panne','Accident'],d.type))+'</div><div style="margin:12px 0">'+select('Véhicule / TVH','stage',options(stages,d.stage))+'</div>'+groupForm(d,true)+'<details><summary>Lieux, sous-groupes et commentaires — facultatif</summary><div style="display:grid;gap:9px;margin-top:12px">'+locationField(d,'location','Lieu de panne / accident')+locationField(d,'depot','Dépôt / garage — facultatif')+locationField(d,'destination','Destination TVH en France — facultative')+locationField(d,'beneficiaryDestination','Destination des bénéficiaires')+'</div><button type="button" class="small ghost" data-action="add-group">'+icon('plus')+' Ajouter un sous-groupe</button><label class="field" style="margin-top:12px">Commentaires<textarea name="notes">'+esc(d.notes)+'</textarea></label></details>'+(criticalOnly?'</details>':'')+'<button type="submit" class="primary full">'+icon('check')+' ENREGISTRER</button></form>'+(isExisting?assignmentUI.taskRows(d.id,true):'')+'<div class="actions" style="margin-top:12px"><button class="small ghost" data-action="new-agent">Nouveau dossier</button><a href="./" target="_blank" style="font-size:11px">Ouvrir la supervision ↗</a></div></div></div><div class="notice">Données fictives · sauvegarde locale. Les onglets du même navigateur partagent les modifications ; aucune synchronisation entre appareils.</div></main>';
 applyTheme(document.body.dataset.theme||'light');
 $('#agent-form').onsubmit=e=>{e.preventDefault();capture();const typed=normalizeId($('#agent-id').value);if((!agentLoadedId||typed!==agentLoadedId)&&state.cases.some(x=>normalizeId(x.id)===typed)){toast('Ce dossier est déjà enregistré. Ouvrez le dossier existant.',true);return}if(agentLoadedId&&typed!==agentLoadedId){toast('Le numéro d’un dossier existant ne peut pas être modifié. Utilisez Nouveau dossier.',true);return}agentEditing.id=typed;persistDraft(agentEditing,!agentLoadedId)};
 $('#agent-id').oninput=e=>{const id=normalizeId(e.target.value),exists=state.cases.some(x=>normalizeId(x.id)===id);$('#duplicate').innerHTML=exists&&id!==agentLoadedId?'Ce dossier est déjà enregistré. <button type="button" class="link-button" data-action="find-agent-case">Ouvrir le dossier existant</button>':exists?'Dossier existant ouvert pour mise à jour.':'';$('#agent-assignees').innerHTML=agentAssignmentBanner(id)};
}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function settings(){showModal('<h2>Paramètres & données</h2><p>Laboratoire local en données fictives. Ces réglages ne créent aucun accès multi-utilisateur.</p><form id="rules-form"><div class="form-grid">'+field('Statuts sans mise à jour : signaler après (h)','staleHours','number',state.settings.staleHours,'min="1" max="8760"')+'</div><div class="actions"><button type="submit" class="primary">Enregistrer les règles</button></div></form><div class="section-title">Aide à l’affectation</div><div class="actions"><button data-engine="settings">Paramètres du moteur</button><button data-engine="simulate">SIMULER UNE AFFECTATION</button></div><div class="section-title">Sauvegarde de démonstration</div><div class="actions" style="justify-content:flex-start"><button data-action="export">'+icon('download')+' Export JSON</button><button id="import-json-button">'+icon('upload')+' Import JSON</button><input type="file" accept=".json,application/json" id="import-json" hidden><button class="danger" data-action="reset-demo">Réinitialiser la démonstration</button></div><div class="section-title">Accès rapide</div><div class="actions" style="justify-content:flex-start"><button data-action="agent-window">'+icon('window')+' Ouvrir l’interface chargé</button><button data-action="install">Installer la PWA</button></div><div class="notice">Carte routière : Esri World Street Map (Esri, HERE, Garmin, USGS, NGA). Recherche : Nominatim, sur validation explicite, sans autocomplétion réseau. Routage : démonstration publique OSRM, sans garantie de disponibilité. Les positions initiales sont des repères de villes publiques, jamais des garages réels.</div><div class="actions"><button data-action="close-modal">Fermer</button></div>',()=>{
 $('#rules-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const cfg=Object.fromEntries(['staleHours'].map(k=>[k,Number(f.get(k))]));try{const next=structuredClone(state);next.settings=cfg;validateState(next);for(const d of next.cases){const a=priority(d,state.settings),b=priority(d,cfg);if(a.key!==b.key)record(d,'Règles de supervision modifiées : '+PRIORITIES[a.key].label+' → '+PRIORITIES[b.key].label+' · '+b.reason)}state=next;closeModal();commit('Règles enregistrées')}catch(e){toast(e.message,true)}};
 $('#import-json-button').onclick=()=>$('#import-json').click();$('#import-json').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>15*1024*1024)throw Error('Fichier trop volumineux (15 Mo maximum).');const imported=validateState(JSON.parse(await file.text()));confirmAction('Importer cette démonstration ?',imported.cases.length+' dossiers et '+imported.agents.length+' chargés remplaceront les données locales actuelles. Exportez-les d’abord si nécessaire.',()=>{state=imported;closeDrawer();agentEditing=null;agentLoadedId=null;commit('Données de démonstration importées')})}catch(e){toast(e.message,true)}};
 })}
function requestArchive(id){const d=state.cases.find(d=>d.id===id);if(!d)return;if(!ready(d)){toast('Terminez le parcours du véhicule et de tous les bénéficiaires avant l’archivage.',true);return}confirmAction('Archiver le dossier '+id+' ?','Il quittera les vues actives et restera disponible dans Archives avec son historique. Les tâches encore ouvertes seront marquées terminées.',()=>{for(const t of state.tasks.filter(t=>t.caseId===d.id&&t.status!=='done'))finishTask(state,t.id);archive(d);closeDrawer();commit('Dossier archivé')})}
function requestAssign(id,agentId){assignmentUI.requestCaseAssignment(id,agentId)}
function refreshOpenCase(id){if(selected===id){editing=structuredClone(state.cases.find(d=>d.id===id));draftRevision=storageRevision;renderDrawer()}}
function requestRemoveAssignee(id,agentId){const d=state.cases.find(d=>d.id===id);if(!d)return;try{removeAssignee(state,d,agentId);commit('Chargé retiré du dossier '+id);refreshOpenCase(id)}catch(e){toast(e.message,true)}}
function chooseAssignees(id){assignmentUI.openRecommendations(id,'',true)}

function editShift(id){const a=state.agents.find(a=>a.id===id),sh=a.schedule.find(s=>s.date===planningDate)||{date:planningDate,start:'08:00',end:'17:00',breakStart:'12:00',breakEnd:'13:00',unavailable:false,reason:''};showModal('<h2>'+esc(a.name)+'</h2><p>Planning du '+planningDate+' · heure de Paris. Pour un poste de nuit, la date est celle de la prise de poste.</p><form id="shift-form"><div class="form-grid">'+field('Prise de poste','start','time',sh.start,'required')+field('Fin de service','end','time',sh.end,'required')+field('Début pause','breakStart','time',sh.breakStart,'required')+field('Fin pause','breakEnd','time',sh.breakEnd,'required')+'</div><label class="check-line" style="margin-top:16px"><input type="checkbox" name="unavailable" '+(sh.unavailable?'checked':'')+'> Indisponible / repos</label>'+field('Motif de l’indisponibilité','reason','text',sh.reason)+'<div class="actions"><button type="button" data-action="close-modal">Annuler</button><button type="submit" class="primary">Enregistrer</button></div></form>',()=>{$('#shift-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),next=structuredClone(state),agent=next.agents.find(x=>x.id===id);const updated={date:planningDate,start:f.get('start'),end:f.get('end'),breakStart:f.get('breakStart'),breakEnd:f.get('breakEnd'),unavailable:f.has('unavailable'),reason:f.get('reason')};agent.schedule=agent.schedule.filter(s=>s.date!==planningDate);agent.schedule.push(updated);agent.planningSource='manual';try{validateState(next);state=next;closeModal();commit('Planning enregistré')}catch(e){toast(e.message,true)}}})}
function editAgent(id){const a=state.agents.find(a=>a.id===id);showModal('<h2>Profil du chargé</h2><p>Collaborateur fictif · langues réellement utilisées pour les contrôles d’affectation.</p><form id="profile-form"><div class="form-grid">'+field('Nom fictif','name','text',a.name,'required')+field('Service','service','text',a.service,'required')+field('Capacité indicative (dossiers)','capacity','number',a.capacity,'min="1" max="200" required')+'</div><div class="tags">'+Object.entries(LANGUAGES).map(([l,name])=>'<label class="check-line"><input type="checkbox" name="languages" value="'+l+'" '+(a.languages.includes(l)?'checked':'')+'>'+name+'</label>').join('')+'</div><div class="actions"><button type="button" data-action="close-modal">Annuler</button><button type="submit" class="primary">Enregistrer</button></div></form>',()=>{$('#profile-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.getAll('languages').length){toast('Attribuez au moins une langue.',true);return}Object.assign(a,{name:String(f.get('name')),service:String(f.get('service')),capacity:Number(f.get('capacity')),languages:f.getAll('languages')});closeModal();commit('Profil enregistré')}})}
function planningTemplate(){download('manager-control-planning-modele.csv','agent_id;date;start;end;break_start;break_end;unavailable;reason\n'+state.agents.slice(0,3).map(a=>a.id+';'+planningDate+';08:00;17:00;12:00;13:00;false;').join('\n'),'text/csv;charset=utf-8')}
function importPlanning(){showModal('<h2>Importer un planning fictif</h2><p>CSV (virgule ou point-virgule) ou Excel .xlsx/.xls. Colonnes : agent_id, date (AAAA-MM-JJ), start, end, break_start, break_end, unavailable, reason. Le modèle CSV est disponible dans la page Équipes.</p><label class="field">Fichier de démonstration<input type="file" id="planning-file" accept=".csv,.xlsx,.xls"></label><div id="planning-import-result"></div><div class="actions"><button data-action="close-modal">Fermer</button></div>',()=>{$('#planning-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Fichier trop volumineux (5 Mo maximum).');if(!window.XLSX)throw Error('Lecteur Excel indisponible. Rechargez l’application.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false,raw:true});const rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{raw:true,defval:''});if(!rows.length||rows.length>10000)throw Error('Le planning doit contenir entre 1 et 10 000 lignes.');const next=structuredClone(state),errors=[],changed=[];const seen=new Set();
 const norm=k=>k.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\s-]+/g,'_');
 for(let i=0;i<rows.length;i++){const r=Object.fromEntries(Object.entries(rows[i]).map(([k,v])=>[norm(k),String(v).trim()]));const a=next.agents.find(a=>a.id===r.agent_id||a.name.toLowerCase()===String(r.agent||r.nom||r.collaborateur).toLowerCase());let dt=r.date;if(/^\d+(\.\d+)?$/.test(dt)&&Number(dt)>20000){const parsed=XLSX.SSF.parse_date_code(Number(dt));if(parsed)dt=String(parsed.y)+'-'+String(parsed.m).padStart(2,'0')+'-'+String(parsed.d).padStart(2,'0')}else if(/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(dt)){const [d,m,y]=dt.split('/');dt=y+'-'+m.padStart(2,'0')+'-'+d.padStart(2,'0')}const validTime=v=>{if(/^0?\.\d+$/.test(v)){const n=Math.round(Number(v)*1440);return String(Math.floor(n/60)%24).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}if(/^\d{1,2}:\d{2}(:\d{2})?$/.test(v))return v.split(':').slice(0,2).map(x=>x.padStart(2,'0')).join(':');return v};const sh={date:dt,start:validTime(r.start||r.debut||''),end:validTime(r.end||r.fin||''),breakStart:validTime(r.break_start||r.pause_debut||'00:00'),breakEnd:validTime(r.break_end||r.pause_fin||'00:00'),unavailable:['true','1','oui','yes'].includes((r.unavailable||r.indisponible||'').toLowerCase()),reason:r.reason||r.motif||''};const key=a?.id+'|'+dt;if(!a||seen.has(key)||!/^\d{4}-\d{2}-\d{2}$/.test(dt)||!['start','end','breakStart','breakEnd'].every(k=>/^([01]\d|2[0-3]):[0-5]\d$/.test(sh[k]))||sh.start===sh.end){errors.push('Ligne '+(i+2)+' : collaborateur, date, horaires ou doublon invalide.');continue}seen.add(key);a.schedule=a.schedule.filter(s=>s.date!==dt);a.schedule.push(sh);a.planningSource='import';if(a.presence.status==='available')a.presence={status:'unconfirmed'};changed.push(a.name+' · '+dt+' · '+sh.start+' – '+sh.end)}
 if(errors.length)throw Error(errors.slice(0,8).join(' '));validateState(next);$('#planning-import-result').innerHTML='<div class="notice">'+changed.length+' journées valides. Aucun changement avant confirmation.</div><p style="font-size:11px">'+changed.slice(0,8).map(esc).join('<br>')+'</p><button class="primary" id="apply-planning" style="margin-top:15px">Confirmer l’import</button>';$('#apply-planning').onclick=()=>{state=next;closeModal();commit(changed.length+' journées importées')};
 }catch(e){$('#planning-import-result').innerHTML='<div class="notice error">'+esc(e.message)+'</div>'}}})}
let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
document.addEventListener('click',e=>{
 if(suppressClick){e.preventDefault();suppressClick=false;return}
 const v=e.target.closest('[data-view]');if(v){e.preventDefault();setView(v.dataset.view);return}
 const op=e.target.closest('[data-open]');if(op){closeModal();openCase(op.dataset.open);return}
 const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
 if(action==='toggle-theme'){toggleTheme();return}
 if(action==='agent-critical'){capture();const enabled=agentEditing.priorityMode==='manual'&&agentEditing.priority==='critical';agentEditing.priorityMode=enabled?'auto':'manual';agentEditing.priority=enabled?'normal':'critical';agentEditing.priorityReason=enabled?'':'Signalé comme critique';renderAgent();return}
 if(action==='map-fullscreen'){toggleMapFullscreen();return}
 if(action==='close-modal'){closeModal();return}if(action==='close-drawer'){closeDrawer();return}
 if(action==='new'){showModal('<h2>Nouveau dossier</h2><p>Un identifiant unique suffit pour commencer. La fiche pourra être enrichie progressivement.</p><form id="new-form">'+field('Numéro de dossier','id','text','','required autocomplete="off"')+'<div id="new-duplicate" class="notice warn" hidden></div>'+select('Pays','country',countryOptions('FR'))+select('Assistance','type',options(['Panne','Accident'],'Panne'))+'<div class="actions"><button type="button" data-action="close-modal">Annuler</button><button class="primary" type="submit">Créer le dossier</button></div></form>',()=>{const form=$('#new-form'),number=$('[name=id]',form);number.oninput=()=>{const d=state.cases.find(d=>normalizeId(d.id)===normalizeId(number.value)),msg=$('#new-duplicate');msg.hidden=!d;msg.innerHTML=d?'Ce dossier est déjà enregistré. <button type="button" class="link-button" data-open="'+d.id+'">Ouvrir le dossier existant</button>':''};form.onsubmit=e=>{e.preventDefault();try{const f=new FormData(form),d=createCase(state,Object.fromEntries(f));save();closeModal();render();openCase(d.id);toast('Dossier créé, complétez les informations utiles')}catch(e){toast(e.message,true)}}});return}
 if(action==='view-archives'){setView('archives');return}
 if(action==='choose-assignees'){chooseAssignees(id);return}
 if(action==='remove-assignee'){requestRemoveAssignee(id,el.dataset.agent);return}
 if(action==='edit-case'){drawerMode='edit';renderDrawer();return}
 if(action==='cancel-case-edit'){editing=structuredClone(state.cases.find(d=>d.id===selected));drawerMode='view';renderDrawer();return}
 if(action==='tvh-edit'){closeModal();openTVHProcedure(id);return}
 if(action==='save-tvh'){saveTVHProcedure();return}
 if(action==='tvh-list'){openTVHList();return}
 if(action==='tvh-status'){closeModal();changeTVHStatus(id,el.dataset.status);return}
 if(action==='save-case'){capture();persistDraft(editing);return}
 if(action==='locate'){locate(el.dataset.field);return}if(action==='search-map'){locate('location',true);return}
 if(action==='add-group'||action==='remove-group'){capture();const d=view==='agent'?agentEditing:editing;if(action==='add-group')d.groups.push({id:'g'+Date.now(),name:'Sous-groupe '+(d.groups.length+1),adults:1,children:0,vulnerable:false,animals:false,status:BENEFITS[2]});else if(d.groups.length>1)d.groups.splice(+el.dataset.index,1);view==='agent'?renderAgent():renderDrawer();return}
 if(action==='archive'){requestArchive(id);return}if(action==='reopen'){const d=state.cases.find(d=>d.id===id);confirmAction('Réouvrir le dossier '+id+' ?','Il rejoindra les dossiers actifs en prise en charge.',()=>{reopen(d);closeDrawer();commit('Dossier réouvert')});return}
 if(action==='map-overview'){filters.country='';filters.region=null;savedMapViewport=null;render();return}
 if(action==='clear-region'){filters.region=null;render();return}
 if(action==='reset-filters'){filters={country:'',region:null,agent:'',priority:'',stage:'',type:'',q:'',from:'',to:''};render();return}
 if(action==='dates'){showModal('<h2>Période des dossiers</h2><p>Date d’ouverture pour les vues actives ; date de clôture dans les archives.</p><form id="dates-form"><div class="form-grid">'+field('Du','from','date',filters.from)+field('Au','to','date',filters.to)+'</div><div class="actions"><button type="button" data-action="close-modal">Annuler</button><button type="submit" class="primary">Appliquer</button></div></form>',()=>{$('#dates-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('from')&&f.get('to')&&f.get('from')>f.get('to')){toast('La date de fin précède le début.',true);return}filters.from=f.get('from');filters.to=f.get('to');closeModal();render()}});return}
 if(action==='cases-list'||action==='cases-kanban'){dossierMode=action==='cases-list'?'list':'kanban';render();return}
 if(action==='teams-assign'||action==='teams-planning'){teamMode=action==='teams-assign'?'assign':'planning';render();return}
 if(action==='settings'){settings();return}
 if(action==='export'){download('manager-control-demo-'+parisDate()+'.json',JSON.stringify(state,null,2));toast('Export JSON préparé');return}
 if(action==='reset-demo'){confirmAction('Réinitialiser la démonstration ?','Les modifications locales seront remplacées par 72 nouveaux scénarios fictifs. Exportez-les auparavant si nécessaire.',()=>{state=validateState(seed());closeDrawer();agentEditing=null;agentLoadedId=null;commit('Démonstration réinitialisée')});return}
 if(action==='agent-window'){e.preventDefault();setView('agent');return}
 if(action==='new-agent'){agentLoadedId=null;agentEditing=defaultAgentDraft();draftRevision=storageRevision;renderAgent();return}
 if(action==='find-agent-case'){const id=normalizeId($('#agent-id').value);const d=state.cases.find(x=>normalizeId(x.id)===id);if(!d){toast('Aucun dossier enregistré sous ce numéro. Vous pouvez le créer.',true);return}closeModal();openCase(d.id);return}
 if(action==='edit-shift'){editShift(id);return}if(action==='edit-agent'){editAgent(id);return}
 if(action==='planning-template'){planningTemplate();return}if(action==='import-planning'){importPlanning();return}
 if(action==='install'){if(installPrompt){installPrompt.prompt();installPrompt=null}else toast('Dans le menu du navigateur, utilisez « Installer l’application » ou « Ajouter à l’écran d’accueil » si disponible.');return}
});
document.addEventListener('change',e=>{
 if(e.target.closest('#agent-form')&&e.target.name?.startsWith('signal_')){handleAgentSignal(e.target);return}
 const form=e.target.closest('#detail-form,#agent-form');if(form?.id==='agent-form'&&e.target.name==='stage'){capture();moveStage(agentEditing,e.target.value);return}if(form&&['stage','tvh'].includes(e.target.name)){const stage=$('[name=stage]',form),tvh=$('[name=tvh]',form);if(stage&&tvh){if(e.target.name==='stage'){if(stage.value==='TVH en préparation')tvh.value='En attente';else if(stage.value==='TVH en cours')tvh.value='En cours';else if(stage.value==='Livré après TVH')tvh.value='Livré';else if(['En cours','Livré'].includes(tvh.value))tvh.value='En attente'}else{if(tvh.value==='En cours')stage.value='TVH en cours';else if(tvh.value==='Livré')stage.value='Livré après TVH';else if(tvh.value==='En attente')stage.value='TVH en préparation';else if(stage.value.startsWith('TVH ')||stage.value==='Livré après TVH')stage.value='Réparé'}}}

 if(e.target.id==='region-filter'){const region=availableRegions.find(f=>f.properties.id===e.target.value);filters.region=region||null;render();return}
 if(e.target.matches('[data-filter]')){if(e.target.dataset.filter==='country')filters.region=null;filters[e.target.dataset.filter]=e.target.value;render();return}
 if(e.target.name==='quickStatus'){capture();agentEditing.groups[0].status=e.target.value;renderAgent();return}
 if(e.target.id==='completed'){completed=e.target.checked;map?.update(state,filtered(state,{...filters,tvh:view==='tvh'}),view,mapOptions());return}
 if(e.target.id==='flow-type'){flowType=e.target.value;map?.update(state,filtered(state,{...filters,tvh:view==='tvh'}),view,mapOptions());return}
 const ids={'agent-language':'language','agent-availability':'availability','agent-service':'service'};
 if(ids[e.target.id]){if(e.target.id==='agent-language')agentLanguage=e.target.value;if(e.target.id==='agent-availability')agentAvailability=e.target.value;if(e.target.id==='agent-service')agentService=e.target.value;render();return}
 if(e.target.id==='planning-date'){planningDate=e.target.value;render();return}
});
let searchTimer;document.addEventListener('input',e=>{if(e.target.matches('[data-filter=q]')){const value=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{filters.q=value;render();const input=$('[data-filter=q]');input?.focus();input?.setSelectionRange(value.length,value.length)},300)}if(e.target.id==='agent-query'){const value=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{agentQuery=value;render();$('#agent-query')?.focus()},300)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(mapFullscreen&&!$('#modal-root').innerHTML&&!$('#drawer-root').innerHTML){toggleMapFullscreen();return}if($('#modal-root').innerHTML)closeModal();else closeDrawer()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-open][role=button]')){e.preventDefault();openCase(e.target.dataset.open)}});
document.addEventListener('dragstart',e=>{if(pointerDrag){e.preventDefault();return}const c=e.target.closest('[data-case]');if(c){e.dataTransfer.setData('text/plain',c.dataset.case);e.dataTransfer.effectAllowed='move'}});
document.addEventListener('dragover',e=>{const t=e.target.closest('[data-drop]');if(t){e.preventDefault();t.classList.add('drop-over');e.dataTransfer.dropEffect='move'}});
document.addEventListener('dragleave',e=>{const t=e.target.closest('[data-drop]');if(t&&!t.contains(e.relatedTarget))t.classList.remove('drop-over')});
document.addEventListener('drop',e=>{const t=e.target.closest('[data-drop]');$$('.drop-over').forEach(x=>x.classList.remove('drop-over'));if(!t)return;e.preventDefault();const id=e.dataTransfer.getData('text/plain'),d=state.cases.find(x=>x.id===id);if(!d)return;if(t.dataset.drop==='archive')requestArchive(id);if(t.dataset.drop==='assign')requestAssign(id,t.dataset.agent);if(t.dataset.drop==='stage'){try{moveStage(d,t.dataset.stage);commit('Étape du véhicule mise à jour')}catch(e){toast(e.message,true)}}});
window.addEventListener('storage',e=>{if(e.key===THEME_KEY){applyTheme(e.newValue);return}if(e.key===KEY&&e.newValue){try{state=validateState(JSON.parse(e.newValue));storageRevision++;if(view==='agent'&&$('#agent-assignees'))$('#agent-assignees').innerHTML=agentAssignmentBanner($('#agent-id')?.value||agentLoadedId);if(view==='tvh'){map?.destroy();map=null;savedMapViewport=null}if(view!=='agent')render();if(editing||view==='agent')toast('Données modifiées dans une autre fenêtre. Rouvrez le dossier avant de modifier.',true);else toast('Données actualisées depuis l’autre fenêtre')}catch{toast('Une modification externe est illisible et a été ignorée.',true)}}});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>toast('Installation hors ligne indisponible ; l’application reste utilisable en ligne.',true)));
if(view!=='agent')document.body.classList.toggle('map-fullscreen',mapFullscreen);
try{applyTheme(localStorage.getItem(THEME_KEY)||'dark')}catch{applyTheme('light')}
render();

// Pointer-based dragging also supports touch screens and consistent browser automation.
function applyDrop(id,target){const d=state.cases.find(x=>x.id===id);if(!d||!target)return;if(target.dataset.drop==='archive')requestArchive(id);if(target.dataset.drop==='assign')requestAssign(id,target.dataset.agent);if(target.dataset.drop==='stage'){try{moveStage(d,target.dataset.stage);commit('Étape du véhicule mise à jour')}catch(e){toast(e.message,true)}}}
document.addEventListener('pointerdown',e=>{const card=e.target.closest('[data-case]');if(!card||e.button!==0)return;pointerDrag={id:card.dataset.case,x:e.clientX,y:e.clientY,card,ghost:null};if(card.closest('.leaflet-container')){e.preventDefault();e.stopPropagation()}},true);
document.addEventListener('pointermove',e=>{if(!pointerDrag)return;const p=pointerDrag;if(!p.ghost&&Math.hypot(e.clientX-p.x,e.clientY-p.y)>7){p.ghost=document.createElement('div');p.ghost.className='case-card drag-ghost';const d=state.cases.find(d=>d.id===p.id);p.ghost.innerHTML='<b>'+esc(p.id)+'</b><p>'+esc(d?.stage||'Dossier')+'</p>';document.body.append(p.ghost);document.body.classList.add('is-dragging');}if(!p.ghost)return;e.preventDefault();p.ghost.style.left=e.clientX+12+'px';p.ghost.style.top=e.clientY+8+'px';$$('.drop-over').forEach(x=>x.classList.remove('drop-over'));document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]')?.classList.add('drop-over');},{passive:false});
document.addEventListener('pointerup',e=>{if(!pointerDrag)return;const p=pointerDrag;pointerDrag=null;if(!p.ghost)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]');p.ghost.remove();document.body.classList.remove('is-dragging');$$('.drop-over').forEach(x=>x.classList.remove('drop-over'));suppressClick=true;setTimeout(()=>suppressClick=false,100);applyDrop(p.id,target)});
document.addEventListener('pointercancel',()=>{pointerDrag?.ghost?.remove();pointerDrag=null;document.body.classList.remove('is-dragging');$$('.drop-over').forEach(x=>x.classList.remove('drop-over'))});

function readTVHForm(d,form){const f=new FormData(form);for(const k of ['tvh','tvhOriginCountry','tvhDestinationCountry','tvhOriginPrecision','tvhDestinationPrecision'])d[k]=String(f.get(k)||d[k]);return d}
function openTVHProcedure(id){const d=state.cases.find(d=>d.id===id);if(!d||d.archived)return;assignmentUI.close();selected=id;editing=structuredClone(d);normaliseTVH(editing);if(editing.tvh==='Non applicable')editing.tvh='En attente';drawerMode='tvh';draftRevision=storageRevision;renderTVHDrawer(editing)}
function renderTVHDrawer(d){$('#drawer-root').innerHTML='<div class="drawer-shade" data-action="close-drawer"></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="Procédure TVH '+esc(d.id)+'"><header class="drawer-head"><div><div class="eyebrow">Procédure TVH · transport de véhicule</div><h1>'+esc(d.id)+'</h1></div><button class="ghost" data-action="close-drawer" aria-label="Fermer la procédure TVH">'+icon('close')+'</button></header><div class="drawer-body">'+tvhProcedure(d,{countryOptions,locationField})+'</div><footer class="drawer-foot"><button data-action="close-drawer">Annuler</button><button class="primary" data-action="save-tvh">Enregistrer le TVH</button></footer></aside>'}
function refreshTVHMap(){savedMapViewport=null;map?.destroy();map=null}
function saveTVHProcedure(){try{if(draftRevision!==storageRevision)throw Error('Les données ont changé dans une autre fenêtre. Rouvrez la procédure TVH.');capture();const next=structuredClone(state),target=next.cases.find(d=>d.id===editing.id);updateTVH(target,editing);validateState(next);state=next;if(target.tvh==='Livré')completed=true;if(view==='agent'){agentLoadedId=target.id;agentEditing=structuredClone(target)}closeDrawer();refreshTVHMap();commit('TVH enregistré · '+target.tvh+' · '+country(target.tvhDestinationCountry).name);draftRevision=storageRevision}catch(e){toast(e.message,true)}}
function changeTVHStatus(id,status){try{const next=structuredClone(state),d=next.cases.find(d=>d.id===id);if(!d||d.archived)return;updateTVH(d,{tvh:status});validateState(next);state=next;if(status==='Livré')completed=true;closeDrawer();refreshTVHMap();commit('TVH '+id+' · '+status+' · '+country(d.tvhDestinationCountry).name)}catch(e){toast(e.message,true)}}
function openTVHList(){const rows=filtered(state,{...filters,region:null,tvh:true});showModal('<h2>TVH · transport des véhicules</h2><p>Adresses de départ et d’arrivée facultatives. La destination TVH est toujours la France.</p>'+tvhSummary(rows)+'<label class="field">Rechercher un numéro<input id="tvh-lookup" placeholder="Numéro de dossier" autocomplete="off"></label><div id="tvh-list-content">'+tvhTable(rows)+'</div><div class="actions"><button data-action="close-modal">Fermer</button></div>',()=>{$('#tvh-lookup').oninput=e=>{$('#tvh-list-content').innerHTML=tvhTable(rows.filter(d=>d.id.toLowerCase().includes(e.target.value.toLowerCase())))}})}

document.addEventListener('input',e=>{if(e.target.closest('#agent-form')&&/^g[0-9]+_(adults|children)$/.test(e.target.name||'')){const total=$$('input[name$="_adults"],input[name$="_children"]',$('#agent-form')).reduce((n,input)=>n+Math.max(0,Number(input.value)||0),0);if($('#agent-person-total'))$('#agent-person-total').textContent=total+' personne(s)'}});

function caseSignalSummary(d){const active=PRIORITY_SIGNALS.filter(s=>d.signals?.[s.key]);return active.length?'<div class="case-signal-summary">'+active.map(s=>'<span class="signal-chip '+s.priority+'">'+esc(s.label)+'</span>').join('')+'</div>':''}
function agentSignalsForm(d){normaliseSignals(d);const active=PRIORITY_SIGNALS.filter(s=>d.signals[s.key]).length;return '<section class="agent-signal-section"><div id="agent-priority-preview">'+badge(d)+'</div><details open><summary>Signalements prioritaires'+(active?' · '+active:'')+'</summary><div class="agent-signal-options">'+PRIORITY_SIGNALS.map(s=>'<label class="agent-signal '+s.priority+'"><input type="checkbox" name="signal_'+s.key+'" '+(d.signals[s.key]?'checked':'')+'><span>'+esc(s.label)+'</span></label>').join('')+'</div><small class="muted">Rouge : urgent. Noir : critique, prioritaire sur le rouge. Sur un dossier déjà ouvert, le signalement est enregistré immédiatement.</small></details></section>'}
function handleAgentSignal(input){const key=input.name.slice(7),checked=input.checked;normaliseSignals(agentEditing);agentEditing.signals[key]=checked;const typed=normalizeId($('#agent-id')?.value),existing=agentLoadedId===typed&&state.cases.find(d=>d.id===typed);try{if(existing){const stale=draftRevision!==storageRevision;const previous=structuredClone(existing);const p=setPrioritySignal(state,existing,key,checked);if(!save()){Object.assign(existing,previous);throw Error(storageError)}agentEditing.signals={...existing.signals};const taskSection=$('.agent-page .task-section');if(taskSection)taskSection.outerHTML=assignmentUI.taskRows(existing.id,true);if(!stale)draftRevision=storageRevision;toast('Signalement enregistré · '+PRIORITIES[p.key].label)}else toast('Priorité mise à jour · enregistrez le nouveau dossier pour transmettre le signalement');if($('#agent-priority-preview'))$('#agent-priority-preview').innerHTML=badge(agentEditing);const summary=input.closest('details')?.querySelector('summary');if(summary)summary.textContent='Signalements prioritaires · '+PRIORITY_SIGNALS.filter(s=>agentEditing.signals[s.key]).length}catch(e){input.checked=!checked;agentEditing.signals[key]=!checked;toast(e.message,true)}}
